const $=id=>document.getElementById(id);
const fullscreenButton=document.getElementById("fullscreen-toggle");
const gameStage=document.getElementById("stage");
function syncFullscreenButton(){
 const active=!!document.fullscreenElement;
 fullscreenButton.textContent=active?"⤢":"⛶";
 fullscreenButton.setAttribute("aria-label",active?"Esci da schermo intero":"Attiva schermo intero");
 fullscreenButton.title=active?"Esci da schermo intero":"Schermo intero";
}
fullscreenButton.addEventListener("click",async()=>{
 try{
  if(!document.fullscreenElement){
   if(gameStage.requestFullscreen) await gameStage.requestFullscreen();
   else if(gameStage.webkitRequestFullscreen) gameStage.webkitRequestFullscreen();
  }else{
   if(document.exitFullscreen) await document.exitFullscreen();
   else if(document.webkitExitFullscreen) document.webkitExitFullscreen();
  }
 }catch(err){
  const msg="Il browser non ha consentito l'attivazione dello schermo intero. Prova ad aprire il gioco direttamente in Chrome o Edge e ripeti il comando.";
  if(typeof open==="function") open("SCHERMO INTERO",msg,[["Chiudi",close]]);
 }
 syncFullscreenButton();
});
document.addEventListener("fullscreenchange",syncFullscreenButton);
document.addEventListener("webkitfullscreenchange",syncFullscreenButton);

