// EQUILIBRI 3.56 — sistema economico realistico, difficoltà media.
const ECONOMY_BASELINE = {
  gdp:2200, growth:1.4, inflation:2.3, unemployment:7.4,
  debt:3036, deficit:3.2, revenue:930, spending:1000,
  interest:78, investment:62, confidence:54, productivity:100,
  taxPressure:42, welfare:0, energySecurity:62, industry:100,
  month:1, quarter:1, year:2033, lastDecision:"Nessuna nuova misura approvata",
  measures:[], history:[]
};
function ensureEconomy(){
  const base=JSON.parse(JSON.stringify(ECONOMY_BASELINE));
  govState.economy=Object.assign(base,govState.economy||{});
  const e=govState.economy;
  ["measures","history"].forEach(k=>{if(!Array.isArray(e[k]))e[k]=[]});
  Object.keys(base).forEach(k=>{if(typeof base[k]==="number"&&!Number.isFinite(Number(e[k])))e[k]=base[k]});
  // Il calendario segue il turno politico: 12 mesi per anno, 3 per trimestre.
  const elapsed=Math.max(1,Number(turn)||1);
  e.month=((elapsed-1)%12)+1;
  e.year=2033+Math.floor((elapsed-1)/12);
  e.quarter=Math.floor((e.month-1)/3)+1;
  return e;
}
ensureEconomy();

function exportEquilibriSave(){
 const payload={format:"EQUILIBRI_SAVE",version:1,gameVersion:"3.44",savedAt:new Date().toISOString(),government:govState,turn:localStorage.getItem("equilibri_turn")||"1"};
 const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"});
 const url=URL.createObjectURL(blob);const a=document.createElement("a");
 a.href=url;a.download="EQUILIBRI_salvataggio_"+new Date().toISOString().slice(0,10)+".json";
 document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
 open("PARTITA SALVATA","Il file di salvataggio è stato scaricato. Conservalo per poter riprendere la partita anche su un altro dispositivo.",[["Chiudi",close]]);
}
function importEquilibriSave(file){
 const reader=new FileReader();
 reader.onload=()=>{
  try{
   const data=JSON.parse(String(reader.result||""));
   const state=data&&data.format==="EQUILIBRI_SAVE"?data.government:data;
   if(!state||typeof state!=="object"||Array.isArray(state)||!state.election||!state.ministerTrust)throw new Error("File non valido");
   localStorage.setItem("equilibri_government",JSON.stringify(state));
   if(data.turn!==undefined)localStorage.setItem("equilibri_turn",String(data.turn));
   open("PARTITA CARICATA","Il salvataggio è stato caricato. Ricarica il gioco per applicare tutti i dati.",[["Ricarica gioco",()=>location.reload()],["Chiudi",close]]);
  }catch(err){open("ERRORE DI CARICAMENTO","Il file selezionato non è un salvataggio EQUILIBRI valido.",[["Chiudi",close]])}
 };
 reader.readAsText(file);
}
