  <div class="gov-panel" style="margin:10px 0"><h3>Organizza un'iniziativa</h3><div class="elect-stats"><div class="elect-stat"><b>${e.campaignBudget}</b><span>Risorse residue</span></div><div class="elect-stat"><b>${e.campaignLog.length}</b><span>Iniziative svolte</span></div><div class="elect-stat"><b>${e.campaignScore>0?"+":""}${e.campaignScore}</b><span>Impatto accumulato</span></div></div>
   <label class="par-label" for="campaign-region">Territorio</label><select id="campaign-region"><option value="capitale">Capitale e città maggiori</option><option value="industriale">Distretti industriali</option><option value="rurale">Aree rurali e agricole</option><option value="periferia">Periferie e piccoli centri</option><option value="universitaria">Città universitarie</option></select>
   <label class="par-label" for="campaign-topic">Tema dell'iniziativa</label><select id="campaign-topic"><option value="lavoro">Lavoro e salari</option><option value="economia">Imprese e fisco</option><option value="servizi">Sanità e istruzione</option><option value="territorio">Infrastrutture e ambiente</option><option value="sicurezza">Sicurezza e giustizia</option></select>
   <label class="par-label" for="campaign-format">Tipo di intervento</label><select id="campaign-format"><option value="ascolto">Assemblea di ascolto · costo 2</option><option value="tavolo">Tavolo con categorie e amministratori · costo 3</option><option value="programma">Presentazione di una proposta concreta · costo 4</option><option value="crisi">Gestione pubblica di una contestazione · costo 2</option></select>
   <button id="campaign-action" ${e.result!==null||e.campaignBudget<2?"disabled":""}>Realizza l'iniziativa scelta</button>
   <div class="campaign-log">${e.campaignLog.length?e.campaignLog.slice(0,5).map(x=>`<p><b>${escapeHtml(x.title)}</b><br><small>${escapeHtml(x.region)} · ${escapeHtml(x.topic)} · ${escapeHtml(x.outcome)}</small></p>`).join(""):'<p>Nessuna iniziativa ancora svolta.</p>'}</div></div>
