function ensureSociety(){
 govState.society=govState.society||{wellbeing:52,inequality:48,trust:50,unrest:18,services:54,history:[]};
 const x=govState.society;
 ["wellbeing","inequality","trust","unrest","services"].forEach(k=>{x[k]=Math.max(0,Math.min(100,Number(x[k]??50)));});
 x.history=Array.isArray(x.history)?x.history:[];
 govState.publicOpinion=govState.publicOpinion||{};
 PUBLIC_BLOCS.forEach(b=>{if(!Number.isFinite(Number(govState.publicOpinion[b.id])))govState.publicOpinion[b.id]=50;});
 return x;
}
function showSociety(){
 const x=ensureSociety(),e=ensureEconomy(),p=govState.parliament||{};
 const blocRows=PUBLIC_BLOCS.map(b=>{const v=Number(govState.publicOpinion[b.id]??50);return `<div class="soc-bloc"><div><b>${escapeHtml(b.name)}</b><strong>${v}/100</strong></div><div class="soc-track"><i style="width:${v}%"></i></div><small>${v>=65?"Consenso favorevole":v>=45?"Opinione divisa":"Malcontento diffuso"}</small></div>`}).join("");
 const parties=Object.entries(p.relations||{}).map(([id,v])=>`<span class="soc-party">${escapeHtml(id)} <b>${Math.round(v)}/100</b></span>`).join("");
 const actions=[
  {id:"consult",name:"Consultazione pubblica",desc:"Ascolta associazioni, sindacati e territori prima di definire le priorità.",cost:1,changes:{trust:4,unrest:-2},blocs:{famiglie:1,lavoratori:2,territori:3,giovani:2}},
  {id:"services",name:"Piano straordinario per i servizi",desc:"Rafforza temporaneamente sanità territoriale, scuola e servizi sociali.",cost:5,changes:{wellbeing:3,services:5,unrest:-3},blocs:{famiglie:3,servizi:4,giovani:2}},
  {id:"prices",name:"Sostegno temporaneo contro il caro-vita",desc:"Aiuto mirato alle famiglie vulnerabili; costa al bilancio e non risolve le cause strutturali dei prezzi.",cost:4,changes:{wellbeing:2,inequality:-2,unrest:-2},blocs:{famiglie:4,lavoratori:2,imprese:-1}},
  {id:"territories",name:"Patto con i territori",desc:"Accordi con amministrazioni locali e parti sociali per servizi, manutenzione e inclusione.",cost:3,changes:{trust:3,services:2,unrest:-2},blocs:{territori:4,imprese:1,servizi:1}}
 ];
 const used=govState.societyActions||{};
 $("content").innerHTML=`<div class="society-screen">
 <div class="soc-head"><div><span class="soc-kicker">QUADRO SOCIALE · ${gameCalendarLabel()}</span><h2>Società e cittadini</h2><p>La società non è un indicatore unico: gruppi diversi reagiscono in modo diverso alle scelte del Governo.</p></div><div class="soc-mood"><small>Indice di benessere</small><b>${Math.round(x.wellbeing)}/100</b><span>${x.unrest>=60?"Tensione elevata":x.unrest>=35?"Tensione presente":"Tensione contenuta"}</span></div></div>
 <div class="soc-metrics">
 ${[["Benessere",x.wellbeing],["Fiducia nelle istituzioni",x.trust],["Qualità dei servizi",x.services],["Disuguaglianza",x.inequality],["Tensione sociale",x.unrest]].map(([n,v])=>`<div class="soc-metric"><span>${n}</span><b>${Math.round(v)}/100</b><div class="soc-track"><i style="width:${v}%"></i></div></div>`).join("")}
 </div>
 <section class="soc-panel"><h3>Opinione pubblica per gruppi sociali</h3><p>Il consenso è persistente e cambia con le leggi promulgate e le decisioni sociali.</p><div class="soc-blocs">${blocRows}</div></section>
 <section class="soc-panel"><h3>Rapporti con le forze politiche</h3><p>Il malcontento sociale può trasformarsi in pressione sui partiti della maggioranza.</p><div class="soc-parties">${parties||"I rapporti politici saranno registrati dopo la formazione del Governo."}</div></section>
 <section class="soc-panel"><h3>Interventi sociali del Governo</h3><p>Ogni intervento ha un costo immediato e benefici mirati. Puoi adottare ciascuna misura una volta per turno.</p><div class="soc-actions">${actions.map(a=>{const done=used[`${turn}:${a.id}`];return `<article class="soc-action"><div><h4>${a.name}</h4><p>${a.desc}</p><small>Costo: ${a.cost} miliardi · una volta per turno</small></div><button data-soc-action="${a.id}" ${done?"disabled":""}>${done?"Già adottato":"Adotta misura"}</button></article>`}).join("")}</div></section>
 <section class="soc-panel"><h3>Situazione economica e sociale</h3><p>Spesa pubblica: ${fmtBn(e.spending)} · Entrate: ${fmtBn(e.revenue)} · Saldo: ${fmtBn(e.revenue-e.spending)}.</p><p>Le misure sociali aumentano la spesa e possono migliorare benessere e fiducia; il loro effetto è graduale e non sostituisce una riforma strutturale.</p></section>
 </div>`;
 $("content").querySelectorAll("[data-soc-action]").forEach(btn=>btn.onclick=()=>{
  const a=actions.find(z=>z.id===btn.dataset.socAction);if(!a)return;
  govState.societyActions=govState.societyActions||{};const key=`${turn}:${a.id}`;
  if(govState.societyActions[key])return;
  // Il Tesoro non usa una cassa separata: la misura è finanziata dal bilancio e aumenta il fabbisogno.
  e.spending+=a.cost;e.debt=Math.max(0,e.debt+a.cost);e.deficit=(e.spending-e.revenue)/Math.max(1,e.gdp)*100;
  Object.entries(a.changes).forEach(([k,v])=>x[k]=Math.max(0,Math.min(100,x[k]+v)));
  Object.entries(a.blocs).forEach(([k,v])=>govState.publicOpinion[k]=Math.max(0,Math.min(100,Number(govState.publicOpinion[k]??50)+v)));
  govState.publicApproval=Math.max(5,Math.min(95,(govState.publicApproval??54)+1));
  govState.societyActions[key]=true;x.history.unshift({turn,action:a.name,cost:a.cost});x.history=x.history.slice(0,20);
  if(typeof saveGov==="function")saveGov();showSociety();
 });
 $("actions").innerHTML='<button id="soc-back">Torna al Governo</button><button id="soc-close">Chiudi</button>';
 $("soc-back").onclick=showGovernment;$("soc-close").onclick=close;
 $("veil").style.display="flex";$("dialog").classList.add("gov-dialog");
}
function gameCalendarLabel(){
 const elapsed=Math.max(1,Number(turn)||1);
 const month=((elapsed-1)%12),year=2033+Math.floor((elapsed-1)/12),quarter=Math.floor(month/3)+1;
 const names=["Gennaio","Febbraio","Marzo","Aprile","Maggio","Giugno","Luglio","Agosto","Settembre","Ottobre","Novembre","Dicembre"];
 return `${names[month]} ${year} · Trimestre ${quarter}`;
}

function liveEventData(){
 const p=govState.parliament||{}, bills=Array.isArray(p.bills)?p.bills:[];
 const pending=govState.pendingTurnEvent||null;
 const history=Array.isArray(govState.turnHistory)?govState.turnHistory:[];
 const activeBills=bills.filter(b=>!b.promulgated&&!["Respinta","Ritirata","Decaduta"].includes(String(b.status||"")));
 const remainingMonths=b=>Math.max(0,Number(b.deadlineTurn||((Number(b.createdAt)||Number(turn)||1)+6))-(Number(turn)||1));
 const nearBills=activeBills.filter(b=>remainingMonths(b)<=1);
 const commissionBills=activeBills.filter(b=>/commission|istruttoria|esame/i.test(String(b.status||""))||b.commissionStage);
 const alerts=[];
 if(pending) alerts.push({kind:"decision",title:pending.title||"Evento in attesa",detail:"È richiesta una decisione del Governo."});
 nearBills.forEach(b=>alerts.push({kind:"deadline",title:"Scadenza legislativa vicina",detail:(b.title||"Disegno di legge")+" · verifica l'iter e il tempo residuo."}));
 commissionBills.forEach(b=>alerts.push({kind:"commission",title:"Lavori in commissione",detail:(b.title||"Disegno di legge")+" · istruttoria o deliberazione in corso."}));
 if(p.crisis) alerts.push({kind:"crisis",title:"Crisi parlamentare",detail:"La partita registra una crisi di Governo."});
 if(Number(govState.stability??65)<38) alerts.push({kind:"stability",title:"Stabilità di Governo critica",detail:"La stabilità è scesa sotto 38/100."});
 return {pending,history,activeBills,nearBills,commissionBills,alerts};
}
function showEventNotifications(){
 const d=liveEventData();
 const rows=d.alerts.length?d.alerts.map(a=>`<div class="par-history-entry"><b>${escapeHtml(a.title)}</b><span>${escapeHtml(a.detail)}</span></div>`).join(""):'<p class="eco-note">Nessuna notifica urgente. Non risultano decisioni sospese, scadenze imminenti o crisi registrate.</p>';
 open("Notifiche della partita",`<div class="par-card"><h3>Attenzione richiesta · ${d.alerts.length}</h3>${rows}</div><div class="par-card"><p>Le notifiche sono ricavate dai dati correnti della partita e si aggiornano quando avanzi il mese o risolvi un evento.</p></div>`,[["Centro eventi",showEventCenter],["Chiudi",close]]);
}
function showEventCenter(){
 const d=liveEventData();
 const pendingHtml=d.pending?`<div class="par-card"><div class="par-card-head"><h3>Decisione in sospeso</h3><span class="status-pill">Richiede scelta</span></div><h4>${escapeHtml(d.pending.title||"Evento")}</h4><p>${escapeHtml(d.pending.body||"È disponibile una decisione del Consiglio.")}</p><button class="par-action" id="event-resolve">Esamina e decidi</button></div>`:'<div class="par-card"><h3>Nessuna decisione in sospeso</h3><p>Il Governo non ha eventi in attesa di una scelta. Il prossimo evento sarà generato dalle condizioni effettive del Paese e delle istituzioni.</p></div>';
 const alertHtml=d.alerts.filter(a=>a.kind!=="decision").map(a=>`<div class="par-history-entry"><b>${escapeHtml(a.title)}</b><span>${escapeHtml(a.detail)}</span></div>`).join("")||'<p class="eco-note">Nessuna scadenza o criticità istituzionale rilevata.</p>';
 const billsHtml=d.activeBills.length?d.activeBills.slice(0,10).map(b=>{const left=Math.max(0,Number(b.deadlineTurn||((Number(b.createdAt)||Number(turn)||1)+6))-(Number(turn)||1));return `<div class="par-history-entry"><b>${escapeHtml(b.title||"Disegno di legge")}</b><span>${escapeHtml(b.status||"Iter in corso")} · ${left===0?"scadenza raggiunta":left+" mesi alla scadenza"}</span></div>`}).join(""):'<p class="eco-note">Non ci sono disegni di legge attualmente in iter.</p>';
 const historyHtml=d.history.length?d.history.slice(0,12).map(x=>`<div class="par-history-entry"><b>${escapeHtml(x.event||"Evento")}</b><span>Turno ${Number(x.turn)||"—"} · ${escapeHtml(x.decision||"Decisione registrata")} · Consenso ${Math.round(Number(x.approval??0))}/100 · Stabilità ${Math.round(Number(x.stability??0))}/100</span></div>`).join(""):'<p class="eco-note">La cronologia si popolerà con le decisioni prese durante la partita.</p>';
 $("title").textContent="Centro eventi · "+gameCalendarLabel();
 $("content").innerHTML=`<div class="par-hero"><div><small>VALDORIA · CRONOLOGIA ISTITUZIONALE</small><h2>Centro eventi</h2><p>Situazioni, decisioni e passaggi generati dai dati della partita corrente.</p></div></div>${pendingHtml}<div class="par-card"><div class="par-card-head"><h3>Segnalazioni e scadenze</h3><span>${d.alerts.length} notifiche</span></div>${alertHtml}</div><div class="par-card"><h3>Leggi in corso</h3>${billsHtml}</div><div class="par-card"><h3>Eventi e decisioni già registrati</h3>${historyHtml}</div>`;
 $("actions").innerHTML='<button id="event-center-close">Chiudi</button>';
 const resolve=$("content").querySelector("#event-resolve");
 if(resolve)resolve.onclick=()=>{const p=govState.pendingTurnEvent;if(!p)return;open("Evento · "+p.title,p.body+"<br><br><b>Scegli come intervenire.</b>",p.choices.map((c,i)=>[c.label,()=>applyTurnChoice(i)]).concat([["Decidi più tardi",close]]));};
 $("event-center-close").onclick=close;
 $("veil").style.display="flex";
}

