 const opinion=PUBLIC_BLOCS.map(b=>Number(govState.publicOpinion?.[b.id]??50));
 const avgOpinion=opinion.length?opinion.reduce((a,b)=>a+b,0)/opinion.length:50;
 const activeBills=(p.bills||[]).filter(b=>!b.promulgated&&!["Respinta","Ritirata","Approvata","Promulgata"].includes(b.status));
