 const history=e.history||[];
 const previous=history[0]||null;
 const coalition=(p.partners||[]).map(x=>typeof x==="string"?x:(x.name||x.id||x.partyId)).filter(Boolean);
 const relationEntries=Object.entries(p.relations||{});
 const weakest=relationEntries.length?relationEntries.sort((a,b)=>Number(a[1])-Number(b[1]))[0]:null;
