 const closeBtn=document.createElement("button");closeBtn.textContent="Chiudi";closeBtn.onclick=close;$("actions").appendChild(closeBtn);
 $("content").querySelectorAll("[data-eco-measure]").forEach(btn=>btn.addEventListener("click",()=>reviewEconomyMeasure(btn.dataset.ecoMeasure)));
