/* Navigazione contestuale v3.1: cronologia affidabile + accesso diretto alla schermata principale. */
(function(){
 const routeNames = ["showProfileEditor","showElection","showElectionTransition","showCabinetFormation",
  "showGovernment","showParliament","showMinister","showCabinetMeeting","showSettings"];
 const routeStack=[];
 let currentRoute=null, navigating=false;
 function home(){
  navigating=true;
  routeStack.length=0;
  try{
   if(!govState.election || govState.election.result===null || govState.election.result===undefined){
    showStartScreen();currentRoute={name:"showStartScreen",args:[]};
   }else if(!govState.cabinetFormed){
    showCabinetFormation();currentRoute={name:"showCabinetFormation",args:[]};
   }else if(!govState.cabinetInOffice || !govState.parliament?.confidence){
    govState.parliament=govState.parliament||{};
    govState.parliament.activeTab="partiti";
    showParliament();currentRoute={name:"showParliament",args:[]};
   }else{
    showGameDashboard();currentRoute={name:"showGameDashboard",args:[]};
   }
  }finally{navigating=false;}
 }
 routeNames.forEach(name=>{
  const original=window[name];
  if(typeof original!=="function") return;
  window[name]=function(...args){
   if(!navigating && currentRoute && (currentRoute.name!==name ||
      JSON.stringify(currentRoute.args)!==JSON.stringify(args))){
    routeStack.push({name:currentRoute.name,args:currentRoute.args});
    if(routeStack.length>60) routeStack.shift();
   }
   currentRoute={name,args};
   return original.apply(this,args);
  };
 });
 function addNavigation(){
  const actions=document.getElementById("actions");
  const veil=document.getElementById("veil");
  if(!actions || !veil || veil.style.display!=="flex") return;
  if(!document.getElementById("context-back")){
   const back=document.createElement("button");
   back.id="context-back";back.type="button";back.className="secondary";
   back.textContent="← Indietro";back.title="Torna alla schermata precedente";
   back.onclick=()=>{
    const previous=routeStack.pop();
    if(!previous){home();return;}
    const fn=window[previous.name];
    if(typeof fn!=="function"){home();return;}
    navigating=true;
    try{fn.apply(window,previous.args);currentRoute=previous;}
    finally{navigating=false;}
   };
   actions.prepend(back);
  }
  if(!document.getElementById("context-home")){
   const main=document.createElement("button");
   main.id="context-home";main.type="button";main.className="secondary";
   main.textContent="⌂ Principale";main.title="Torna alla schermata principale";
   main.onclick=home;
   actions.appendChild(main);
  }
 }
 const observer=new MutationObserver(addNavigation);
 ["title","content","actions","veil"].forEach(id=>{
  const el=document.getElementById(id);
  if(el) observer.observe(el,{childList:true,subtree:true,characterData:true,attributes:id==="veil",attributeFilter:id==="veil"?["style"]:undefined});
 });
 window.addEventListener("keydown",e=>{
  if(e.altKey && e.key==="ArrowLeft"){e.preventDefault();document.getElementById("context-back")?.click();}
 });
})();


